 function renderCharts(rows,dynamics){
  const end=rows.at(-1).t_s||1;
  function chart(label,series,max,colors,thresholds=[],min=0){
   if(!Array.isArray(thresholds))thresholds=[thresholds];
   const y=value=>65-Math.max(0,Math.min(1,(value-min)/(max-min)))*53;
   const line=key=>rows.map((p,i)=>`${i?'L':'M'}${(p.t_s/end*1000).toFixed(2)},${y(p[key]??0).toFixed(2)}`).join(' ');
   return `<div class="sim-chart"><div class="sim-chart-label">${label}</div><svg viewBox="0 0 1000 75" preserveAspectRatio="none" aria-label="${label}" role="img">${thresholds.map(limit=>`<line x1="0" x2="1000" y1="${y(limit)}" y2="${y(limit)}" stroke="#c39c70" stroke-dasharray="5 5"/>`).join('')}${series.map((s,i)=>`<path d="${line(s)}" fill="none" stroke="${colors[i]}" stroke-width="1.5" vector-effect="non-scaling-stroke"/>`).join('')}<line class="chart-cursor" x1="0" x2="0" y1="0" y2="75" stroke="#ecf3e0" stroke-width="1" vector-effect="non-scaling-stroke"/></svg></div>`;
  }
  if(dynamics){$('#mission-charts').innerHTML=chart('SPEED / m/s',['speed_m_s'],Math.max(.1,...rows.map(p=>p.speed_m_s)),['#d7edb0'])+chart('MOBILITY BUS / W',['mobility_bus_power_w'],Math.max(50,...rows.map(p=>p.mobility_bus_power_w)),['#9ebcd4']);return;}
  let temperatureChart='';
  if(run.thermal_model){
   const properties=run.request.thermal,min=Math.min(run.metrics.minimum_battery_temperature_c,properties.operating_min_c)-5,max=Math.max(run.metrics.maximum_battery_temperature_c,properties.operating_max_c)+5;
   temperatureChart=chart(`BATTERY / °C · ${num(min,0)} TO ${num(max,0)} · AMBER: OPERATING LIMITS`,['battery_temperature_c'],max,['#9ebcd4'],[properties.operating_min_c,properties.operating_max_c],min);
  }
  $('#mission-charts').innerHTML=chart('BATTERY / Wh',['battery_wh'],run.metrics.capacity_wh,['#d7edb0'],run.metrics.reserve_wh)+chart('SOLAR / LOAD · W',['solar_w','load_w'],Math.max(80,...rows.map(p=>Math.max(p.solar_w,p.load_w))),['#d7edb0','#9ebcd4'])+temperatureChart+`<div class="sim-chart sim-contact"><div class="sim-chart-label">EARTH CENTER / GEOMETRIC</div><div class="contact-track">${rows.slice(0,-1).map((p,i)=>`<span style="left:${p.t_s/end*100}%;width:${(rows[i+1].t_s-p.t_s)/end*100}%;background:${p.earth_center_visible?'#6d865b':'#2c343a'}"></span>`).join('')}<i class="contact-cursor"></i></div></div>`;
 }
 function seek(t){
  if(!run||disposed)return;const rows=run.timeline||run.trace;cursor=Math.max(0,Math.min(t,rows.at(-1).t_s));let lo=0,hi=rows.length-1;while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(rows[mid].t_s<=cursor)lo=mid;else hi=mid-1;}
  const a=rows[lo],b=rows[Math.min(lo+1,rows.length-1)],fraction=b.t_s>a.t_s?(cursor-a.t_s)/(b.t_s-a.t_s):0;
  const pose={...a};for(const key of ['east_m','north_m','up_m'])pose[key]=a[key]+(b[key]-a[key])*fraction;scene?.setPose(pose);
  $('#mission-scrubber').value=cursor;$('#mission-elapsed').textContent=time(cursor);
  if(a.utc){
   const delta=cursor-a.t_s,leap=a.utc.includes(':60.');
   $('#mission-utc').textContent=leap&&delta<1? a.utc.replace('T',' ').slice(0,19)+' UTC' :new Date(Date.parse(leap?a.utc.replace(':60.',':59.'):a.utc)+delta*1000).toISOString().replace('T',' ').slice(0,19)+' UTC';
  }else $('#mission-utc').textContent=run.time_origin_utc?new Date(Date.parse(run.time_origin_utc)+cursor*1000).toISOString().replace('T',' ').slice(0,19)+' UTC':'Elapsed physical simulation time';
  const ratio=cursor/(rows.at(-1).t_s||1);$$('.chart-cursor').forEach(line=>{line.setAttribute('x1',ratio*1000);line.setAttribute('x2',ratio*1000);});const contact=$('.contact-cursor');if(contact)contact.style.left=ratio*100+'%';
  if($('#live-state'))$('#live-state').innerHTML=`<div><dt>Current activity</dt><dd>${escapeHTML(a.mode)}</dd></div><div><dt>Battery</dt><dd>${num(a.battery_wh)} Wh</dd></div><div><dt>Solar / load</dt><dd>${num(a.solar_w,0)} / ${num(a.load_w,0)} W</dd></div><div><dt>Sun elevation</dt><dd>${num(a.sun_elevation_deg,2)}°</dd></div><div><dt>Visible solar disk</dt><dd>${num(a.solar_visible_fraction*100,0)}%</dd></div><div><dt>Earth center</dt><dd>${a.earth_center_visible?'Visible':'Occluded'}</dd></div>${run.thermal_model?`<div><dt>Battery temperature</dt><dd>${num(a.battery_temperature_c+(b.battery_temperature_c-a.battery_temperature_c)*fraction)} °C</dd></div><div><dt>Heater delivered</dt><dd>${num(a.heater_delivered_w,1)} W</dd></div><div><dt>Charging</dt><dd>${a.charge_allowed?'Allowed':'Temperature inhibited'}</dd></div>`:''}`;
 }
