  $('#thermal-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button.primary');button.disabled=true;try{const value=structuredClone(thermalConfig);$$('[data-thermal-key]').forEach(input=>value[input.dataset.thermalKey]=Number(input.value));value.solar_normal_body_unit=$('#thermal-normal').value.split(',').map(v=>Number(v.trim()));if(Math.abs(value.ground_temperature_c-thermalConfig.ground_temperature_c)>1e-8)value.ground_reference=null;thermalConfig=await post('/thermal-model/validate',value);invalidateRun();closeDialog();renderSetup();toast('Thermal properties applied to this mission draft.');}catch(error){$('.sim-form-error').hidden=false;$('.sim-form-error').textContent=error.message;$('.sim-form-error').scrollIntoView({block:'nearest'});}finally{button.disabled=false;}};
